func (q *Queries) AggregateCohortInvoicesSeq(ctx context.Context, memberQuery runtime.Query, invoiceStatus string, selectCols ...uint64) iter.Seq2[CohortInvoiceSummary, error] {
	return func(yield func(CohortInvoiceSummary, error) bool) {
		var zero CohortInvoiceSummary
		p := paramsAggregateCohortInvoices{
			MemberQuery:   memberQuery,
			InvoiceStatus: invoiceStatus,
			SelectCols:    runtime.OrCols(selectCols),
		}
		vk, colMask, flagMask, approxArgs := computeAggregateCohortInvoicesKey(p)
		_ = colMask
		argBuf := runtime.AcquireArgsCap(approxArgs)
		defer runtime.ReleaseArgs(argBuf)
		if err := expandAggregateCohortInvoicesParams(argBuf, sqlDialect, p); err != nil {
			yield(zero, err)
			return
		}
		var subsBuf [1]runtime.Query
		subsBuf[0] = p.MemberQuery
		in := runtime.RenderInput{
			ColMask:  colMask,
			FlagMask: flagMask,
			Subs:     subsBuf[:],
		}
		sqlRows, ms, err := q.cache.Query(ctx, q.db, q.txCache, q.usePrepared, vk, stmtIDAggregateCohortInvoices, runtime.ComputeBatchShapeTag(colMask, flagMask), 0, nil, sqlDialect, descAggregateCohortInvoices, &in, (*argBuf)...)
		if err != nil {
			yield(zero, err)
			return
		}
		defer runtime.ReleaseRows(&sqlRows, &ms)
		var item CohortInvoiceSummary
		for sqlRows.Next() {
			if err := scanAggregateCohortInvoicesRow(sqlRows, &item, colMask, p); err != nil {
				runtime.ReleaseRows(&sqlRows, &ms)
				yield(zero, err)
				return
			}
			if !yield(item, nil) {
				return
			}
		}
		err = sqlRows.Err()
		runtime.ReleaseRows(&sqlRows, &ms)
		if err != nil {
			yield(zero, err)
		}
	}
}

